 pub struct RankingsCollectionState {
     pub runtime: Arc<Runtime>,
@@ -133,6 +134,10 @@ impl RankingsCollectionState {
             schedule_step(&ctx, &state).await?;
         }
         Ok(Json(state))
+    }
+
+    #[handler]
+    pub async fn seal(
+        &self,
+        ctx: ObjectContext<'_>,
+        generation: u64,
+    ) -> Result<Json<CollectionState>, HandlerError> {
+        let Some(mut state) = ctx
+            .get::<Json<CollectionState>>("state")
+            .await?
+            .map(|j| j.0)
+        else {
+            return Err(TerminalError::new("no state").into());
+        };
+        if generation != state.generation {
+            return Ok(Json(state));
+        }
+        if !matches!(state.phase, CollectionPhase::Complete) {
+            return Ok(Json(state));
+        }
+        let collection = collection_fingerprint(
+            &state.scope.revision,
+            &state.source_snapshot,
+        ).map_err(terminal)?;
+        let runtime = self.runtime.clone();
+        let state_owned = state.clone();
+        let snapshot = ctx.run(move || async move {
+            let store = runtime.store.clone();
+            runtime.blocking(move || publication::seal(&store, &state_owned, &collection))
+                .await.map(Json).map_err(terminal)
+        }).name("seal completed ranking collection").await?.0;
+        state.final_snapshot = Some(snapshot);
+        ctx.set("state", Json(state.clone()));
+        Ok(Json(state))
     }

     #[handler]
